(6338603, 938840, 10785, '<td valign="top">funny!</td>', 'funny!', '2011-03-02 08:42:22.000000', NULL, 1),
(6338605, 937922, 10785, '<td valign="top">I am not sure the depth of field is needed in this shot. Did you take another shot at a smaller aperture? I would like to see that for comparison.</td>', 'I am not sure the depth of field is needed in this shot. Did you take another shot at a smaller aperture? I would like to see that for comparison.', '2011-03-02 08:43:08.000000', NULL, 1),
