INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6341173, 938777, 121053, '<td valign="top">Cute!  :)</td>', 'Cute!  :)', '2011-03-04 14:38:07.000000', NULL, 1),
(6341174, 937822, 121053, '<td valign="top">So clever.</td>', 'So clever.', '2011-03-04 14:38:56.000000', NULL, 1),
(6341176, 938788, 121053, '<td valign="top">Neat!</td>', 'Neat!', '2011-03-04 14:41:08.000000', NULL, 1),
(6341179, 937799, 121053, '<td valign="top">I like your color choice, the focus of the shot and the reflection.<br/>I am personally always looking for composition.  Sometimes perfect symmetry is preferable to slightly off center.  I would have liked you to move the battery to the exact center of the light circle, and for the circle to be centered exactly.  Or else, move it more to the right so that it is about 1/3 of the way in from the edge.  I know....Picky Picky!</td>', 'I like your color choice, the focus of the shot and the reflection.I am personally always looking for composition.  Sometimes perfect symmetry is preferable to slightly off center.  I would have liked you to move the battery to the exact center of the light circle, and for the circle to be centered exactly.  Or else, move it more to the right so that it is about 1/3 of the way in from the edge.  I know....Picky Picky!', '2011-03-04 14:45:38.000000', NULL, 1),
(6341180, 937844, 121053, '<td valign="top">Cool!</td>', 'Cool!', '2011-03-04 14:46:11.000000', NULL, 1),
