(6341930, 938051, 83686, '<td valign="top">One of the best in this challenge. I like the use of black background and matching border, it really makes the batteries pop. Great job!</td>', 'One of the best in this challenge. I like the use of black background and matching border, it really makes the batteries pop. Great job!', '2011-03-05 10:37:00.000000', NULL, 1),
(6341932, 938640, 83686, '<td valign="top">One of the best in challenge! The colors and clarity are nice. The double reflection will hurt the score a bit but other than that this is a winner!</td>', 'One of the best in challenge! The colors and clarity are nice. The double reflection will hurt the score a bit but other than that this is a winner!', '2011-03-05 10:38:25.000000', NULL, 1),
(6341939, 938832, 83686, '<td valign="top">Good idea but the harsh lighting and background color will bring your score down. To get rid of the reflection build a lightbox with a cardboard box and tissue paper. Also try to minimize reflections to the edge of the subject by adjusting the light or the angle you are shooting from.</td>', 'Good idea but the harsh lighting and background color will bring your score down. To get rid of the reflection build a lightbox with a cardboard box and tissue paper. Also try to minimize reflections to the edge of the subject by adjusting the light or the angle you are shooting from.', '2011-03-05 10:41:13.000000', NULL, 1),
(6341943, 937519, 83686, '<td valign="top">Processing and harsh lighting hurt your shot here. Angle your shot a bit to put the bright light on one side of the subject next time.</td>', 'Processing and harsh lighting hurt your shot here. Angle your shot a bit to put the bright light on one side of the subject next time.', '2011-03-05 10:42:24.000000', NULL, 1),
